package vn.edu.hcmute.example2;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:e2","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc class Example2ApplicationTests {@Autowired MockMvc mvc; @Test void loginIsPublic()throws Exception{mvc.perform(get("/login")).andExpect(status().isOk());} @Test void adminDeniedForUser()throws Exception{mvc.perform(get("/admin").with(user("user").roles("USER"))).andExpect(status().isForbidden());} @Test void adminAllowed()throws Exception{var principal=new AppPrincipal(new AppUser("admin","admin@test.vn","encoded","Quản trị viên","https://example.com/avatar.png","ADMIN"));mvc.perform(get("/admin").with(user(principal))).andExpect(status().isOk());}}
